,p_include_session_state=>'N'
,p_report_layout_id=>wwv_flow_imp.id(3285977276034705101)
,p_format=>'PDF'
,p_output_file_name=>'Departments'
,p_content_disposition=>'ATTACHMENT'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(3285600500818356548)
,p_shared_query_id=>wwv_flow_imp.id(3285600130860356541)
,p_name=>'Departments'
,p_display_sequence=>1
,p_data_loop_name=>'departments'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT deptno,',
'       dname,',
'       JSON_OBJECT(',
'          ''barcodeType'' VALUE ''QR'',',
'          ''data''        VALUE loc,',
'          ''version''     VALUE 10',
'       ) as "{}loc",',
'       JSON_OBJECT(',
'           ''source'' VALUE ''URL'',',
'           ''url''    VALUE ''https://stevemuench.github.io/'' || lower(dname) || ''.png'',',
'           ''width''  VALUE ''150px''',
'       ) AS "{}locGraphic"',
'FROM dept'))
);
end;
